def generate_markdown():
    # Read verses 1 to 10 from current file
    with open('/Users/atishayjain/.gemini/antigravity/scratch/shrutdhara/shastra/ishtopadesha.md', 'r', encoding='utf-8') as f:
        content = f.read()
    
    # We want header + verses 1 to 10
    # Let's find where Verse 11 starts: line 111 (रागद्वेषद्वयीदीर्घनेत्राकर्षणकर्मणा)
    split_marker = "रागद्वेषद्वयीदीर्घनेत्राकर्षणकर्मणा"
    parts = content.split(split_marker)
    header_and_1_to_10 = parts[0].strip()
    
    output = [header_and_1_to_10]
    
    for v in range(11, 52):
        data = verses_data[v]
        mula = data["mula"]
        chhaya = data["chhaya"]
        arth = data["arth"]
        
        verse_block = f"{mula}\n\n@छाया {chhaya}\n\n@अर्थ {arth}"
        output.append(verse_block)
    
    final_md = "\n\n".join(output) + "\n"
    
    target_file = "/Users/atishayjain/.gemini/antigravity/scratch/shrutdhara/shastra/ishtopadesha.md"
    with open(target_file, "w", encoding="utf-8") as f:
        f.write(final_md)
    print(f"Successfully generated {target_file} with all 51 verses!")

